// Promise.all:
function myAll(promises) {
  return new Promise((resolve, reject) => {
    const results = [];
    let count = 0;
    if (!promises.length) return resolve([]);
    promises.forEach((p, i) => {
      Promise.resolve(p).then(val => {
        results[i] = val;
        if (++count === promises.length) resolve(results);
      }).catch(reject); // first rejection wins
    });
  });
}

// Promise.race:
function myRace(promises) {
  return new Promise((resolve, reject) => {
    promises.forEach(p => Promise.resolve(p).then(resolve, reject));
  });
}

// Promise.any:
function myAny(promises) {
  return new Promise((resolve, reject) => {
    const errors = [];
    let rejCount = 0;
    if (!promises.length) return reject(new AggregateError([],'All rejected'));
    promises.forEach((p, i) => {
      Promise.resolve(p)
        .then(resolve)
        .catch(e => {
          errors[i] = e;
          if (++rejCount === promises.length)
            reject(new AggregateError(errors,'All rejected'));
        });
    });
  });
}

// Timeout pattern with Promise.race:
function withTimeout(promise, ms) {
  const timeout = new Promise((_, reject) =>
    setTimeout(() => reject(new Error('Timeout')), ms)
  );
  return Promise.race([promise, timeout]);
}

// These are equivalent:
function fetchUser() {
  return fetch('/api/user').then(r => r.json());
}

async function fetchUser() {
  const r = await fetch('/api/user');
  return r.json(); // return value wrapped in Promise.resolve()
}

// Error handling:
async function safe() {
  try {
    const data = await fetchUser();
  } catch(e) {
    console.error(e); // catches rejected Promise
  }
}
